// DeleteCustomer deletes a customer at the current time. The API uses DeleteCustomerAt with the service's clock.
func (s *Store) DeleteCustomer(orgID, id string) error {
	return s.DeleteCustomerAt(orgID, id, time.Now())
}

// DeleteCustomerAt deletes a customer at now. The customer is hidden, not removed: its invoices and payments keep it, and
// RestoreCustomer can undo the deletion for 30 days. Its email address is free again. A customer with a subscription that
// is not canceled cannot be deleted.
func (s *Store) DeleteCustomerAt(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrActiveSubscriptions
		}
	}
	t := now.UTC()
	c.DeletedAt = &t
	s.customers[id] = c
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
	return nil
}

// RestoreCustomer undoes the deletion of a customer that was deleted no more than 30 days before now. It returns ErrNotFound
// for a customer that is not deleted or was deleted longer ago, and ErrEmailTaken when another customer now uses its email
// address.
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt == nil || now.Sub(*c.DeletedAt) > customerRestoreWindow {
		return Customer{}, ErrNotFound
	}
	key := normEmail(c.Email)
	if other, ok := s.customersByEmail[key]; ok && other != id && s.customers[other].OrgID == orgID {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers removes the customers deleted more than 30 days before now and returns how many it removed. Their
// invoices and payments stay, and their customer on an invoice becomes null.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	cutoff := now.Add(-customerRestoreWindow)
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && c.DeletedAt.Before(cutoff) {
			delete(s.customers, id)
			n++
		}
	}
	return n
}

