func TestDeleteAndRestoreCustomer(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	jane, _ := s.CreateCustomer(a.ID, "Jane Doe", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteCustomerAt(a.ID, jane.ID, t0); !errors.Is(err, ErrActiveSubscriptions) || !errors.Is(err, ErrConflict) {
		t.Fatalf("delete with an active subscription: %v", err)
	}
	if _, ok := s.Customer(a.ID, jane.ID); !ok {
		t.Fatal("a refused delete removed the customer")
	}
	if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, t0)
	if err != nil {
		t.Fatal(err)
	}

	deletedAt := t0.Add(time.Hour)
	if err := s.DeleteCustomerAt(a.ID, jane.ID, deletedAt); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.CustomerWithDeleted(a.ID, jane.ID); !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(deletedAt) {
		t.Fatalf("CustomerWithDeleted = %+v, %v", got, ok)
	}
	if _, ok := s.Customer(a.ID, jane.ID); ok {
		t.Fatal("deleted customer still visible")
	}
	if got := s.Customers(a.ID); len(got) != 0 {
		t.Fatalf("Customers after delete = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers after delete = %+v", got)
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer's email still found")
	}
	if _, ok := s.Invoice(a.ID, inv.ID); !ok {
		t.Fatal("deleting a customer removed its invoice")
	}
	if err := s.DeleteCustomerAt(a.ID, jane.ID, deletedAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted twice: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, jane.ID, func(*Customer) error { return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("update a deleted customer: %v", err)
	}
	if _, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: p.ID, Quantity: 1, Status: Active}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}

	// The email address is free again, so another customer can take it; then the deleted one cannot come back.
	other, err := s.CreateCustomer(a.ID, "Jane Again", "Jane@example.com", t0)
	if err != nil {
		t.Fatalf("reuse of a deleted customer's email: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t0.Add(2*time.Hour)); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email taken: %v", err)
	}
	if err := s.DeleteCustomerAt(a.ID, other.ID, t0.Add(2*time.Hour)); err != nil {
		t.Fatal(err)
	}
	back, err := s.RestoreCustomer(a.ID, jane.ID, t0.Add(2*time.Hour))
	if err != nil || back.DeletedAt != nil || back.ID != jane.ID {
		t.Fatalf("RestoreCustomer = %+v, %v", back, err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != jane.ID {
		t.Fatalf("FindCustomerByEmail after restore = %+v %v", got, ok)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, t0.Add(2*time.Hour)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore a customer that is not deleted: %v", err)
	}

	// Deleted customers survive a snapshot without their email address being claimed.
	if err := s.DeleteCustomerAt(a.ID, jane.ID, t0.Add(3*time.Hour)); err != nil {
		t.Fatal(err)
	}
	restored, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := restored.CustomerWithDeleted(a.ID, jane.ID); !ok || got.DeletedAt == nil {
		t.Fatalf("deleted customer after FromState = %+v, %v", got, ok)
	}
	if _, ok := restored.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("a deleted customer's email is claimed after FromState")
	}
	if _, err := restored.CreateCustomer(a.ID, "Jane Third", "jane@example.com", t0); err != nil {
		t.Fatalf("reuse after FromState: %v", err)
	}
}

func TestRestoreWindowAndPurge(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	old, _ := s.CreateCustomer(a.ID, "Old", "old@example.com", t0)
	later, _ := s.CreateCustomer(a.ID, "Later", "later@example.com", t0)
	live, _ := s.CreateCustomer(a.ID, "Live", "live@example.com", t0)
	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: old.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, t0)
	if err != nil {
		t.Fatal(err)
	}
	day := 24 * time.Hour
	if err := s.DeleteCustomerAt(a.ID, old.ID, t0); err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteCustomerAt(a.ID, later.ID, t0.Add(20*day)); err != nil {
		t.Fatal(err)
	}

	if _, err := s.RestoreCustomer(a.ID, old.ID, t0.Add(30*day+time.Second)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore after 30 days: %v", err)
	}
	if _, err := s.RestoreCustomer(a.ID, live.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore a live customer: %v", err)
	}
	if got := s.PurgeDeletedCustomers(t0.Add(30 * day)); got != 0 {
		t.Fatalf("purge at exactly 30 days removed %d", got)
	}
	if got := s.PurgeDeletedCustomers(t0.Add(31 * day)); got != 1 {
		t.Fatalf("purge at 31 days removed %d, want 1", got)
	}
	if _, ok := s.CustomerWithDeleted(a.ID, old.ID); ok {
		t.Fatal("purged customer still there")
	}
	if _, ok := s.Invoice(a.ID, inv.ID); !ok {
		t.Fatal("purging a customer removed its invoice")
	}
	if _, ok := s.CustomerWithDeleted(a.ID, later.ID); !ok {
		t.Fatal("a customer deleted 11 days ago was purged")
	}
	if got := s.PurgeDeletedCustomers(t0.Add(31 * day)); got != 0 {
		t.Fatalf("second purge removed %d", got)
	}
	if got := s.PurgeDeletedCustomers(t0.Add(51 * day)); got != 1 {
		t.Fatalf("purge of the later customer removed %d", got)
	}
	if got := s.Customers(a.ID); len(got) != 1 || got[0].ID != live.ID {
		t.Fatalf("Customers after purge = %+v", got)
	}
}

