func TestDeleteAndRestoreCustomer(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	john := e.CreateCustomer(e.Acme, "John Roe", "john@example.com")
	plan := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	lines := []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 1000}}
	var inv struct {
		ID       string `json:"id"`
		Customer *struct {
			ID, Name, Email string
			Deleted         bool
		} `json:"customer"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": lines}, &inv)

	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": john.ID, "plan_id": plan.ID}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+john.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+john.ID, e.Acme.Key, nil, nil)

	for _, req := range []struct{ method, body string }{
		{"GET", ""},
		{"PATCH", `{"name":"Johnny"}`},
		{"DELETE", ""},
	} {
		if r := e.Do(req.method, "/v1/customers/"+john.ID, e.Acme.Key, req.body); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
			t.Fatalf("%s after delete: %s", req.method, r)
		}
	}
	var page struct {
		Items []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers", e.Acme.Key, nil, &page)
	if len(page.Items) != 1 || page.Items[0].ID != jane.ID {
		t.Fatalf("list after delete = %+v", page.Items)
	}
	for _, q := range []string{"q=john", "email=john@example.com"} {
		page.Items = nil
		e.MustDo(http.StatusOK, "GET", "/v1/customers?"+q, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("%s after delete = %+v", q, page.Items)
		}
	}
	rows, err := csv.NewReader(strings.NewReader(string(e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil).Body))).ReadAll()
	if err != nil || len(rows) != 2 || rows[1][0] != jane.ID {
		t.Fatalf("export after delete = %v, %v", rows, err)
	}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": john.ID, "currency": "USD", "lines": lines}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for a deleted customer: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": john.ID, "plan_id": plan.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for a deleted customer: %s", r)
	}
	if n := len(e.Store.Events(e.Acme.ID, "customer.deleted")); n != 1 {
		t.Fatalf("customer.deleted events = %d", n)
	}

	// The deleted customer's email is free; restoring it then conflicts with the new customer.
	john2 := e.CreateCustomer(e.Acme, "John Again", "john@example.com")
	if r := e.Do("POST", "/v1/customers/"+john.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email taken: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+john2.ID, e.Acme.Key, nil, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+john.ID+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != john.ID || restored.DeletedAt != nil {
		t.Fatalf("restore = %+v", restored)
	}
	if r := e.Do("POST", "/v1/customers/"+john.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+john.ID, e.Acme.Key, nil, &restored)

	// An invoice keeps its deleted customer, marked as deleted, until the customer is purged after 30 days.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.ID != jane.ID || inv.Customer.Name != "Jane Doe" || inv.Customer.Email != "jane@example.com" || !inv.Customer.Deleted {
		t.Fatalf("invoice customer after delete = %+v", inv.Customer)
	}
	var invs struct {
		Items []struct {
			ID       string `json:"id"`
			Customer *struct {
				ID, Name, Email string
				Deleted         bool
			} `json:"customer"`
		} `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+jane.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].Customer == nil || !invs.Items[0].Customer.Deleted {
		t.Fatalf("invoice list after delete = %+v", invs)
	}

	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	e.Store.PurgeDeletedCustomers(e.Clock.Now())
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer != nil {
		t.Fatalf("invoice customer after purge = %+v", inv.Customer)
	}
}

