func TestFailedCreateLeavesNoCustomer(t *testing.T) {
	e := apitest.New(t)
	if r := e.Do("POST", "/v1/customers", e.Acme.Key, map[string]any{"name": "Jane Doe", "email": "jane@example.com", "default_payment_method": "card"}); r.Code != http.StatusUnprocessableEntity {
