17	func (s *Server) listCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
18		pg, ok := parsePage(w, r)
19		if !ok {
20			return
21		}
22		q := r.URL.Query()
23		var cs []store.Customer
24		switch {
25		case q.Get("email") != "":
26			cs = []store.Customer{}
27			if c, ok := s.store.FindCustomerByEmail(p.OrgID, q.Get("email")); ok {
28				cs = append(cs, c)
29			}
30		case q.Get("q") != "":
31			cs = s.store.SearchCustomers(p.OrgID, q.Get("q"))
32		default:
33			cs = s.store.Customers(p.OrgID)
34		}
35		items, next := pageOf(cs, customerKey, pg)
36		writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
37	}
